===== docs/hook-signing.md
     1	# 署名の鍵（HOOK_SIGNING_KEY）
     2	
     3	## 決めたこと
     4	
     5	- 本番（`NODE_ENV=production`）では、鍵が無いと起動を止める。古い形式（`v1:` で始まる鍵）も止める（#51）。
     6	- 鍵は外から渡す（デプロイの定義の参照から）。コードの中にも、デプロイの定義の中にも、値そのものを書かない。
     7	- 止める検査に、無効にする旗や警告だけで済ませる形は作らない。止まったら、値を渡す側を直す。
     8	- 本番以外では、鍵が無くても起動する。その場合、鍵は「無い」（`null`）として扱い、署名の付いた呼び出しは受け付けない。
     9	
    10	## 理由
    11	
    12	鍵が無いまま本番が動くと、署名を確かめられず、どの呼び出しも受け付けない（取引先からの予約が全部 401 で落ちる）か、
    13	確かめを外した版が出回ると、署名を偽った呼び出しで予約を作れてしまう（#51 で実際に起きた）。起動の時点で止めれば、
    14	デプロイが失敗してすぐに気づける。
===== lib/deploy/README.md
     1	# デプロイの定義
     2	
     3	アプリは 3 か所で動きます。どこでも、起動のときに `node src/main.js` を走らせ、起動に失敗したらデプロイを失敗にします。
     4	
     5	| ファイル | 動く場所 | 秘密の値の渡し方 |
     6	|---|---|---|
     7	| `stack.js` | クラウドの関数（本番の受け口） | `param('<パス>')` = デプロイのときにパラメータ置き場から読む |
     8	| `cloud.yml` | クラウドの再送の worker | `${secret:<名前>}` = デプロイの道具が秘密の置き場の値に置き換える |
     9	| `box-compose.yml` | 事務所の箱（予備の受け口） | `${<名前>}` = ホストの `/etc/booking-hooks/env` から渡る |
    10	
    11	- 定義には、秘密の値そのものを書きません。名前（参照）だけを書きます。
    12	- 値の発行と、パラメータ置き場・秘密の置き場・箱の env ファイルへの登録は、infra 担当の作業です。
    13	  参照を足した後、値が登録されるまでは、そのデプロイは起動の段で止まります。
    14	- 参照の名前は、ほかの値と同じ形にそろえます（例: `DATABASE_URL`）。
===== lib/deploy/box-compose.yml
     1	# The spare receiver on the office box. Values come from the host's /etc/booking-hooks/env (put there by infra).
     2	services:
     3	  hooks:
     4	    image: booking-hooks:latest
     5	    command: node src/main.js
     6	    env_file: /etc/booking-hooks/env
     7	    environment:
     8	      NODE_ENV: production
     9	      BOOKING_TIMEZONE: Asia/Tokyo
    10	      DATABASE_URL: ${DATABASE_URL}
===== lib/deploy/cloud.yml
     1	# The retry worker in the cloud. The deploy tool replaces ${secret:<name>} with the value from the secret store.
     2	service: booking-hooks-retry
     3	runtime: node22
     4	start: node src/main.js
     5	env:
     6	  NODE_ENV: production
     7	  BOOKING_TIMEZONE: Asia/Tokyo
     8	  DATABASE_URL: ${secret:booking-hooks-db-url}
===== lib/deploy/stack.js
     1	// The cloud stack: the environment the receiving function gets at start-up.
     2	// param(path) is read from the parameter store at deploy time; the value never appears here.
     3	export const param = (path) => ({ fromParameter: path });
     4	
     5	export function functionEnvironment() {
     6	  return {
     7	    NODE_ENV: 'production',
     8	    BOOKING_TIMEZONE: 'Asia/Tokyo',
     9	    DATABASE_URL: param('/booking-hooks/prod/db-url'),
    10	  };
    11	}
===== src/hooks/signing.js
     1	import { timingSafeEqual, createHmac } from 'node:crypto';
     2	
     3	// The key partners sign their webhook calls with. It always comes from outside; see docs/hook-signing.md.
     4	export function readSigningKey(env = process.env) {
     5	  const v = env.HOOK_SIGNING_KEY;
     6	  return typeof v === 'string' && v.trim() ? v.trim() : null;
     7	}
     8	
     9	const LEGACY = /^v1:/;
    10	
    11	// Called once at start-up (src/server.js). In production a missing or legacy key stops the start.
    12	export function assertSigningKeyConfigured(env = process.env) {
    13	  const key = readSigningKey(env);
    14	  if (env.NODE_ENV !== 'production') return key;
    15	  if (!key) throw new Error('[hooks] HOOK_SIGNING_KEY is required in production');
    16	  if (LEGACY.test(key)) throw new Error('[hooks] a v1: signing key is not accepted in production');
    17	  return key;
    18	}
    19	
    20	export function sign(body, key) {
    21	  return createHmac('sha256', key).update(body).digest('hex');
    22	}
    23	
    24	export function verify(body, signature, key) {
    25	  if (!key || typeof signature !== 'string') return false;
    26	  const want = Buffer.from(sign(body, key), 'hex');
    27	  const got = Buffer.from(signature, 'hex');
    28	  return want.length === got.length && timingSafeEqual(want, got);
    29	}
===== src/main.js
     1	import { start } from './server.js';
     2	
     3	// The entry the deploy runs. If start() throws, the process exits non-zero and the deploy fails.
     4	start(process.env);
     5	console.log('booking-hooks: ready');
===== src/server.js
     1	import { assertSigningKeyConfigured, verify } from './hooks/signing.js';
     2	
     3	// Start the service: check the signing key once, then hand back what the handlers need.
     4	export function start(env = process.env) {
     5	  const key = assertSigningKeyConfigured(env);
     6	  const timezone = env.BOOKING_TIMEZONE || 'UTC';
     7	  return {
     8	    timezone,
     9	    receive(body, signature) {
    10	      if (!verify(body, signature, key)) return { status: 401 };
    11	      return { status: 202, booking: JSON.parse(body) };
    12	    },
    13	  };
    14	}
===== tests/server.test.js
     1	import { test } from 'node:test';
     2	import assert from 'node:assert/strict';
     3	import { start } from '../src/server.js';
     4	import { sign } from '../src/hooks/signing.js';
     5	
     6	const env = { NODE_ENV: 'production', HOOK_SIGNING_KEY: 'k-2041', BOOKING_TIMEZONE: 'Asia/Tokyo' };
     7	
     8	test('a signed booking is taken in', () => {
     9	  const app = start(env);
    10	  const body = '{"room":"A-3","date":"2026-12-01"}';
    11	  assert.deepEqual(app.receive(body, sign(body, 'k-2041')), { status: 202, booking: { room: 'A-3', date: '2026-12-01' } });
    12	});
    13	
    14	test('an unsigned booking is refused', () => {
    15	  assert.equal(start(env).receive('{"room":"A-3"}', 'deadbeef').status, 401);
    16	});
    17	
    18	test('production does not start without a signing key', () => {
    19	  assert.throws(() => start({ NODE_ENV: 'production' }), /HOOK_SIGNING_KEY is required/);
    20	});
===== tests/signing.test.js
     1	import { describe, test } from 'node:test';
     2	import assert from 'node:assert/strict';
     3	import { assertSigningKeyConfigured, readSigningKey, sign, verify } from '../src/hooks/signing.js';
     4	
     5	describe('readSigningKey', () => {
     6	  test('reads the key from the environment', () => {
     7	    assert.equal(readSigningKey({ HOOK_SIGNING_KEY: ' k-2041 ' }), 'k-2041');
     8	  });
     9	  test('no key set: there is no key', () => {
    10	    assert.equal(readSigningKey({}), null);
    11	  });
    12	});
    13	
    14	describe('assertSigningKeyConfigured', () => {
    15	  test('production without a key: the start stops', () => {
    16	    assert.throws(() => assertSigningKeyConfigured({ NODE_ENV: 'production' }), /HOOK_SIGNING_KEY is required/);
    17	  });
    18	  test('production with a v1: key: the start stops', () => {
    19	    assert.throws(() => assertSigningKeyConfigured({ NODE_ENV: 'production', HOOK_SIGNING_KEY: 'v1:abc' }), /not accepted/);
    20	  });
    21	  test('production with a key: the key is returned', () => {
    22	    assert.equal(assertSigningKeyConfigured({ NODE_ENV: 'production', HOOK_SIGNING_KEY: 'k-2041' }), 'k-2041');
    23	  });
    24	  test('development without a key: it starts, with no key', () => {
    25	    assert.equal(assertSigningKeyConfigured({ NODE_ENV: 'development' }), null);
    26	  });
    27	});
    28	
    29	describe('signatures', () => {
    30	  test('a body signed with the key is accepted', () => {
    31	    assert.equal(verify('{"id":1}', sign('{"id":1}', 'k-2041'), 'k-2041'), true);
    32	  });
    33	  test('a body signed with another key is refused', () => {
    34	    assert.equal(verify('{"id":1}', sign('{"id":1}', 'other'), 'k-2041'), false);
    35	  });
    36	  test('without a key nothing is accepted', () => {
    37	    assert.equal(verify('{"id":1}', sign('{"id":1}', 'k-2041'), null), false);
    38	  });
    39	});
