import { describe, test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { functionEnvironment } from '../lib/deploy/stack.js';
import { start } from '../src/server.js';
import { sign } from '../src/hooks/signing.js';

// The environment a YAML deploy definition hands to the app: the `NAME: value` lines nested under its `<block>:` line.
function yamlEnvironment(file, block) {
  const lines = readFileSync(new URL(`../lib/deploy/${file}`, import.meta.url), 'utf8').split('\n');
  const indent = (line) => line.search(/\S/);
  const head = lines.findIndex((line) => line.trim() === `${block}:`);
  assert.notEqual(head, -1, `${file} has no ${block}: block`);
  const entries = [];
  for (const line of lines.slice(head + 1)) {
    if (line.trim() === '') continue;
    if (indent(line) <= indent(lines[head])) break;
    const [, name, value] = line.match(/^\s*(\w+):\s*(\S.*)$/) ?? [];
    if (name) entries.push([name, value.trim()]);
  }
  return Object.fromEntries(entries);
}

// The three places the app runs (lib/deploy/README.md), and the reference each one passes the signing key with.
const definitions = [
  {
    name: 'stack.js (the cloud function)',
    environment: functionEnvironment(),
    signingKeyReference: { fromParameter: '/booking-hooks/prod/hook-signing-key' },
  },
  {
    name: 'cloud.yml (the retry worker)',
    environment: yamlEnvironment('cloud.yml', 'env'),
    signingKeyReference: '${secret:booking-hooks-hook-signing-key}',
  },
  {
    name: 'box-compose.yml (the office box)',
    environment: yamlEnvironment('box-compose.yml', 'environment'),
    signingKeyReference: '${HOOK_SIGNING_KEY}',
  },
];

const isReference = (value) =>
  typeof value === 'string' ? /^\$\{[^}]+\}$/.test(value) : typeof value?.fromParameter === 'string';

// What the app gets at start-up once infra has registered a value for every reference in the definition.
function withRegisteredValues(environment) {
  return Object.fromEntries(
    Object.entries(environment).map(([name, value]) => [name, isReference(value) ? `registered-${name}` : value]),
  );
}

for (const { name, environment, signingKeyReference } of definitions) {
  describe(name, () => {
    test('with every referenced value registered, the production start-up does not stop', () => {
      const env = withRegisteredValues(environment);
      assert.equal(env.NODE_ENV, 'production');
      const body = '{"room":"A-3","date":"2026-12-01"}';
      const signature = sign(body, 'registered-HOOK_SIGNING_KEY');
      assert.deepEqual(start(env).receive(body, signature), {
        status: 202,
        booking: { room: 'A-3', date: '2026-12-01' },
      });
    });

    test('the signing key is passed as a reference, never as a value', () => {
      assert.deepEqual(environment.HOOK_SIGNING_KEY, signingKeyReference);
    });
  });
}

